(()=>{"use strict";const $=id=>document.getElementById(id),AW={H:1.008,He:4.0026,Li:6.94,Be:9.0122,B:10.81,C:12.011,N:14.007,O:15.999,F:18.998,Ne:20.18,Na:22.99,Mg:24.305,Al:26.982,Si:28.085,P:30.974,S:32.06,Cl:35.45,Ar:39.95,K:39.098,Ca:40.078,Sc:44.956,Ti:47.867,V:50.942,Cr:51.996,Mn:54.938,Fe:55.845,Co:58.933,Ni:58.693,Cu:63.546,Zn:65.38,Br:79.904,I:126.9,Ba:137.33,Pb:207.2,Ag:107.87,Au:196.97,Hg:200.59,Sn:118.71};function parseFormula(f){if(f.length>200)throw"too-long";let i=0;function num(){let s="";for(;i<f.length&&/[0-9]/.test(f[i]);)s+=f[i++];if(s==="")return 1;const value=Number(s);if(s[0]==="0"||!Number.isSafeInteger(value)||value<1)throw"bad-count";return value}function add(out,symbol,count){const value=(out[symbol]||0)+count;if(!Number.isSafeInteger(value)||value<1)throw"bad-count";out[symbol]=value}function group(depth){if(depth>32)throw"too-deep";const out={};for(;i<f.length&&f[i]!==")";)if(f[i]==="("){i++;const inner=group(depth+1);if(f[i]!==")")throw"unbalanced";i++;const m=num();for(const k in inner)add(out,k,inner[k]*m)}else if(/[A-Z]/.test(f[i])){let sym=f[i++];if(i<f.length&&/[a-z]/.test(f[i])&&(sym+=f[i++]),!(sym in AW))throw"unknown:"+sym;add(out,sym,num())}else throw"bad:"+f[i];if(!Object.keys(out).length)throw"empty-group";return out}const res=group(0);if(i!==f.length)throw"unbalanced";return res}function render(){const f=$("formula").value.replace(/\s+/g,"");if(!f){$("result").textContent="\u2014",$("chipComp").textContent="\u2014";const vd2=$("verdict");vd2.className="verdict warn",$("verdictText").textContent="Enter a chemical formula, e.g. H2O.";return}let counts;try{counts=parseFormula(f)}catch(e){$("result").textContent="\u2014",$("chipComp").textContent="\u2014";const vd2=$("verdict");vd2.className="verdict warn",$("verdictText").textContent=String(e).indexOf("unknown:")===0?"Unknown element: "+String(e).slice(8)+". This table covers common elements only.":"Could not parse that formula. Use element symbols with counts, e.g. H2O or Ca(OH)2.";return}let total=0;for(const k in counts)total+=counts[k]*AW[k];$("result").textContent=total.toLocaleString(typeof window<"u"&&window.CMI18n?window.CMI18n.formatLocale:"en-US",{maximumFractionDigits:3,minimumFractionDigits:3})+" g/mol";const parts=[];for(const k in counts)parts.push(k+": "+window.CMI18n.number(counts[k]*AW[k]/total*100,{minimumFractionDigits:2,maximumFractionDigits:2})+"%");$("chipComp").textContent=parts.join(" \xB7 ");const vd=$("verdict");vd.className="verdict",$("verdictText").textContent="One mole of "+f+" weighs "+window.CMI18n.number(total,{minimumFractionDigits:3,maximumFractionDigits:3})+" grams."}document.querySelectorAll("input").forEach(e=>e.addEventListener("input",render)),render()})();
